**The bug:** the `change` listener fired `refreshAll()`, but the select's value was never read, so `getDailyData`/`renderChart`/`renderTable` ran against unfiltered data — every key produced identical output.

**The fix, in four moves:**

**1. Read the value in the refresh entry point and thread it through every function.**

```js
// BEFORE (inert)
select.addEventListener('change', refreshAll);
function refreshAll() {
  const daily = getDailyData();          // value never read
  renderKPIs(daily); renderChart(daily); renderTable(daily);
}

// AFTER
select.addEventListener('change', () => refreshAll(select.value));

function refreshAll(apiKeyName) {
  const daily = getDailyData(apiKeyName);   // threaded as a parameter
  renderKPIs(daily, apiKeyName);
  renderChart(daily, apiKeyName);
  renderTable(daily, apiKeyName);
}
```

**2. Append `WHERE col = ?` only to queries touching the table that has the column** — and use a dedicated `cdWhere`/`cdParams` split for `cost_daily`, which has **no** `api_key_name` column. Leaking the filter there causes a binder error.

```js
function getDailyData(apiKeyName) {
  // api_usage HAS api_key_name → filter here, via parameterized ?-param
  const where = [], params = [];
  if (apiKeyName) { where.push('api_key_name = ?'); params.push(apiKeyName); }

  const apiSql = 'SELECT date, api_key_name, SUM(cost) AS cost FROM api_usage'
               + (where.length ? ' WHERE ' + where.join(' AND ') : '')
               + ' GROUP BY date, api_key_name';

  // cost_daily LACKS api_key_name → its own where/params, always empty.
  // Nothing from the filter may ever touch this query.
  const cdSql    = 'SELECT date, SUM(cost) AS cost FROM cost_daily GROUP BY date';
  const cdParams = [];

  return db.exec(apiSql, params).concat(db.exec(cdSql, cdParams));
}
```

**3. Preserve the select value across `innerHTML` rebuilds** — snapshot before repopulating options, restore after:

```js
function rebuildKeyOptions(keys) {
  const select = document.getElementById('apiKeyFilter');
  const prev = select.value;                       // snapshot
  select.innerHTML =
    '<option value="">All keys</option>' +
    keys.map(k => `<option value="${k}">${k}</option>`).join('');
  select.value = prev;                             // restore
}
```

**4. Unit test** — stub `db.exec` with canned rows per key; assert the totals differ and the SQL carries the filter; guard with a leakage test on `cost_daily`:

```js
const calls = [];
D.setDb({
  exec(sql, params) {
    calls.push({ sql, params });
    if (sql.includes('cost_daily')) return cdRows;         // never filtered
    return rowsByKey[params[0]] || [];                     // canned per key
  },
});

// regression: costA !== costB
const costA = getDailyData('keyA').reduce((s,r)=>s+r.cost,0);
const costB = getDailyData('keyB').reduce((s,r)=>s+r.cost,0);
assert(costA !== costB);

// SQL carries the filter
assert(calls.some(c => c.sql.includes('api_key_name = ?') && c.params[0] === 'keyB'));

// leakage guard: cost_daily never references the column
const cd = calls.find(c => c.sql.includes('cost_daily'));
assert(!/api_key_name/i.test(cd.sql) && cd.params.length === 0);
```
